rowLayout.value:
%{
	//debugger;
	var iWpnSkill = ${switchCase(sameRow('wpnSkill'), 'Archery', POI,'Crossbow', POI,'Light Artillery', POI,'Pistol', POI,'Rifle', POI, 'Stormsmithing', PER, PRW)}$ ;
	var iWpnAtk = ${sameRow('wpnAtk')}$;
	var iWpnAtkMod = ${ WpnAtkMod }$;
	var iSkillLvl = ${first(lookup('MilitarySkills', 'SkillLvl','SName', sameRow('wpnSkill') ))}$;
	if (iSkillLvl == undefined) {
		iSkillLvl = ${first(lookup('OccupationalSkills', 'SkillLvl','SName', sameRow('wpnSkill') ))}$;
	}
	return (iWpnSkill+iWpnAtk+iWpnAtkMod+iSkillLvl);
}%
